const money=v=>'₹'+Number(v).toLocaleString('en-IN');
const duration=m=>`${Math.floor(m/60)}h ${String(m%60).padStart(2,'0')}m`;
const serviceDays=t=>{if(Array.isArray(t.runDates))return`Special dates · ${t.runDates.length} services`;const days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].filter((_,i)=>t.runsOn.includes(i));return days.length===7?'Daily':days.length===5&&['Mon','Tue','Wed','Thu','Fri'].every(day=>days.includes(day))?'Weekdays':days.join(' · ')};
const classForTrain=t=>{const requested=connectionSearch?.cls??searched.cls;return classesFor(t).includes(requested)?requested:classesFor(t)[0]};
const icons={train:'M6 3h12v13H6z M8 7h8 M8 11h1 M15 11h1 M8 16l-2 4 M16 16l2 4 M8 20h8',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',ticket:'M3 6h18v4a2 2 0 0 0 0 4v4H3v-4a2 2 0 0 0 0-4z M15 7v2 M15 12v1 M15 16v1',pin:'M12 21s7-7 7-12a7 7 0 1 0-14 0c0 5 7 12 7 12 M12 6a3 3 0 1 0 0 6 3 3 0 0 0 0-6',food:'M4 3v6c0 3 6 3 6 0V3 M7 3v18 M17 3c-3 4-3 8 1 9v9 M18 3v9',history:'M4 6a9 9 0 1 1-1 8 M4 2v5h5 M12 7v5l3 2',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16 M8 14h2 M14 14h2',logout:'M9 4H4v16h5 M13 7l5 5-5 5 M8 12h13',arrow:'M4 12h16 M15 7l5 5-5 5',swap:'M3 8h17 M16 4l4 4-4 4 M21 16H4 M8 12l-4 4 4 4',wallet:'M4 5h15v15H4z M14 10h7v6h-7z M17 13h1',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M9 9a3 3 0 1 1 4 3v2 M12 17h.01',check:'M5 12l4 4L19 6',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',close:'M5 5l14 14 M19 5L5 19',moon:'M20.7 13.1A8.5 8.5 0 0 1 10.9 3.3 8.7 8.7 0 1 0 20.7 13.1z',sun:'M12 3v2 M12 19v2 M5.64 5.64l1.42 1.42 M16.94 16.94l1.42 1.42 M3 12h2 M19 12h2 M5.64 18.36l1.42-1.42 M16.94 7.06l1.42-1.42 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0'};
