const brand=`<div class="brand"><span class="mark">${icon('train')}</span><div>RailYatra<small>EVERY JOURNEY MATTERS</small></div></div>`;
const art=`<svg class="hero-art" viewBox="0 0 600 240" aria-hidden="true"><defs><linearGradient id="sky"><stop stop-color="#356954"/><stop offset="1" stop-color="#729779"/></linearGradient></defs><circle cx="443" cy="83" r="46" fill="#dfbc79" opacity=".8"/><path d="M0 161L94 58l63 74 78-99 120 112 56-70 81 74 108-103v194H0z" fill="url(#sky)"/><path d="M0 174l121-47 96 35 77-40 110 51 93-51 103 37v81H0z" fill="#376b51"/><path d="M0 224c180-70 340-55 600-15" fill="none" stroke="#93a47a" stroke-width="16"/><path d="M0 224c180-70 340-55 600-15" fill="none" stroke="#193d31" stroke-width="2"/><g transform="translate(165 114) rotate(3)"><path d="M0 43h333l20 20H0z" fill="#e7dbba"/><rect x="4" y="16" width="257" height="49" rx="6" fill="#f1e9d5"/><path d="M263 16h37q33 0 44 31l9 17h-90z" fill="#f1e9d5"/><path d="M298 23q24 0 35 20h-35z" fill="#23554a"/><path d="M5 48h343v8H5z" fill="#e1a75b"/><g fill="#25594c"><rect x="17" y="25" width="28" height="16" rx="3"/><rect x="58" y="25" width="28" height="16" rx="3"/><rect x="99" y="25" width="28" height="16" rx="3"/><rect x="140" y="25" width="28" height="16" rx="3"/><rect x="181" y="25" width="28" height="16" rx="3"/><rect x="222" y="25" width="28" height="16" rx="3"/></g><path d="M52 18v47 M94 18v47 M136 18v47 M178 18v47 M220 18v47" stroke="#c6c4aa"/><g fill="#163e33"><circle cx="30" cy="65" r="7"/><circle cx="81" cy="65" r="7"/><circle cx="151" cy="65" r="7"/><circle cx="206" cy="65" r="7"/><circle cx="284" cy="65" r="7"/><circle cx="324" cy="65" r="7"/></g></g><path d="M540 185v-61l-13 20h26l-19 23h28z" fill="#164334"/><path d="M90 184v-61l-13 20h26l-19 23h28z" fill="#164334"/></svg>`;
let user=null;try{user=JSON.parse(localStorage.getItem('ry-session'));}catch{}
let theme=localStorage.getItem('ry-theme');if(!['light','dark'].includes(theme))theme=window.matchMedia?.('(prefers-color-scheme: dark)').matches?'dark':'light';
let page='book',authMode='login',bookings=[],orders=[],transactions=[],availability={},error='',busy=false,selected=null,step=1,viewTicket=null,historyTab='upcoming',pnrResult=null,tracking=null,detailTrain=null,foodJourney='',modal=null,connectionFlow=null,connectionLegIndex=0,connectionPassengers=[],connectionSearch=null;
let query={from:'SBC',to:'MAS',date:addDays(today(),1),cls:'3A',quota:'GENERAL',count:1};let searched={...query};let filter='All',sort='departure',journeyResultsCacheKey='',journeyResultsCache=[],visibleResultCount=12;let draft=null;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function safeSession(u){return{name:u.name,email:u.email};}
async function refresh(){if(!user){bookings=[];orders=[];transactions=[];availability=backendEnabled()?await getAvailability(searched):{};return;}bookings=await all('bookings');orders=await all('orders');transactions=backendEnabled()?await all('transactions'):[];availability=backendEnabled()?await getAvailability(searched):{};}
function freeSeats(route,cls){if(!backendEnabled())return availableSeats(bookings,route,cls);const entry=availability[route.trainId];return entry?.originDate===route.originDate?entry.classes?.[cls]??[]:[];}
function queueCounts(route,cls){if(backendEnabled()){const entry=availability[route.trainId];return entry?.originDate===route.originDate?entry.queues?.[cls]??{racCount:0,waitlistCount:0}:{racCount:0,waitlistCount:0};}const queued=bookings.filter(b=>b.trainId===route.trainId&&b.originDate===route.originDate&&b.cls===cls&&b.a<route.b&&route.a<b.b&&['RAC','WAITLISTED'].includes(b.status));return{racCount:queued.filter(b=>b.status==='RAC').reduce((n,b)=>n+b.passengers.length,0),waitlistCount:queued.filter(b=>b.status==='WAITLISTED').reduce((n,b)=>n+b.passengers.length,0)};}
function queuePreview(route,cls,count=1){const q=queueCounts(route,cls);if(q.waitlistCount===0&&q.racCount+count<=RAC_CAPACITY){const position=q.racCount+1,end=position+count-1;return{status:'RAC',position,label:`RAC ${position}${count>1?`–${end}`:''}`};}const position=q.waitlistCount+1,end=position+count-1;return{status:'WAITLISTED',position,label:`WL ${position}${count>1?`–${end}`:''}`};}
function bookingStatusLabel(b){if(b.status==='RAC')return`RAC ${b.queuePosition??1}${b.passengers?.length>1?`–${(b.queuePosition??1)+b.passengers.length-1}`:''}`;if(b.status==='WAITLISTED')return`WL ${b.queuePosition??1}${b.passengers?.length>1?`–${(b.queuePosition??1)+b.passengers.length-1}`:''}`;return b.status==='CONFIRMED'?'CNF':'CAN';}
function passengerStatusLabel(b,i){if(b.status==='RAC')return`RAC ${(b.queuePosition??1)+i}`;if(b.status==='WAITLISTED')return`WL ${(b.queuePosition??1)+i}`;return b.status==='CONFIRMED'?'CNF':'CAN';}
function availabilityLabel(route,cls,count=1){const free=freeSeats(route,cls).length,q=queueCounts(route,cls);if(free>0&&q.racCount+q.waitlistCount===0)return`AVL ${free}`;return queuePreview(route,cls,count).label;}
function availabilityTone(route,cls,count=1){const q=queueCounts(route,cls);if(freeSeats(route,cls).length>0&&q.racCount+q.waitlistCount===0)return'status-avl';return queuePreview(route,cls,count).status==='RAC'?'status-rac':'status-wl';}
const mine=()=>bookings.filter(b=>b.email===user?.email);
const upcoming=()=>mine().filter(b=>['CONFIRMED','RAC','WAITLISTED'].includes(b.status)&&Date.parse(b.departure.iso)>=Date.now());
const options=(obj,selected)=>Object.entries(obj).map(([v,n])=>`<option value="${esc(v)}" ${selected===v?'selected':''}>${esc(n)}</option>`).join('');
const stations=(v)=>options(Object.fromEntries(Object.entries(STATIONS).sort((a,b)=>a[1].localeCompare(b[1])).map(([c,n])=>[c,n+' ('+c+')'])),v);
function themeControl(){const dark=theme==='dark',label=dark?'Switch to light theme':'Switch to dark theme';return`<button class="theme-toggle" data-action="theme" aria-pressed="${dark}" aria-label="${label}" title="${label}">${icon(dark?'sun':'moon')}<span>${dark?'Light':'Dark'} mode</span></button>`;}
function render(){document.documentElement.dataset.theme=theme;if(!user){renderAuth();return;}const nav=[['book','search','Book a journey'],['pnr','ticket','PNR enquiry'],['track','pin','Track your train'],['food','food','Food on board'],['journeys','calendar','My journeys'],['transactions','wallet','Transactions'],['help','help','About this demo']];$('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand}<nav><div class="nav-label">YOUR TRAVEL DESK</div>${nav.map(([p,i,n])=>`<button class="nav-button ${page===p?'active':''}" data-nav="${p}" ${page===p?'aria-current="page"':''}>${icon(i)}${n}</button>`).join('')}</nav><div class="sidebar-foot"><div class="demo-tag"><strong>Made for the journey.</strong><br>Independent railway simulator.<br>No live railway or IRCTC API.</div><button class="nav-button" data-action="logout">${icon('logout')}Log out</button></div></aside><main><header class="topbar"><span class="crumb">Your travel desk <span style="margin:0 9px">/</span> ${esc(nav.find(n=>n[0]===page)?.[2]??(page==='checkout'?'Checkout':'Your ticket'))}</span><div class="row">${themeControl()}<span class="badge amber">DEMO MODE</span><span class="avatar">${esc(user.name.slice(0,2).toUpperCase())}</span><span class="tiny">${esc(user.name.split(' ')[0])}</span><button class="text-btn" data-action="logout" aria-label="Log out">${icon('logout')}</button></div></header><div class="content">${page==='book'?dashboard():page==='checkout'?checkout():page==='ticket'?ticketPage():servicePage()}<footer class="main-footer">RailYatra · Independent railway demo. Reference timetable snapshot; availability, tracking and payments are simulated. ${backendEnabled()?'Accounts, bookings, seats and meals sync through the shared demo service.':'Accounts, bookings and meals are saved in this browser.'}<br>No live railway / IRCTC connection. Tickets are not valid for travel.</footer></div></main></div>${modalHtml()}`;if(page==='ticket'&&viewTicket){$('#ticket-qr').src=qrData(viewTicket.pnr);} }
function renderAuth(){ $('#app').innerHTML=`<div class="auth-layout"><section class="auth-story">${brand}<div><div class="eyebrow" style="color:#dcb27b;margin:45px 0 20px">A LITTLE CLOSER TO EVERYWHERE</div><h1>Big adventures.<br>Small towns.<br><em>One beautiful journey.</em></h1><p>From the mountains to the coast, discover India one railway journey at a time.</p>${art}</div><footer>INDEPENDENT RAILWAY BOOKING DEMO · NOT VALID FOR TRAVEL</footer></section><section class="auth-panel">${themeControl()}<div class="auth-form"><span class="eyebrow muted">YOUR NEXT CHAPTER STARTS HERE</span><h2>${authMode==='login'?'Welcome aboard.':'A seat for you.'}</h2><p>${authMode==='login'?'Sign in to your demo travel desk. A whole country of possibilities awaits.':backendEnabled()?'Create an account on the shared demo server and start exploring.':'Create a local demo account and start exploring.'}</p><div class="auth-tabs"><button data-auth="login" class="${authMode==='login'?'active':''}">Sign in</button><button data-auth="signup" class="${authMode==='signup'?'active':''}">Create account</button></div><form id="auth-form">${authMode==='signup'?'<div class="field"><label for="name">Your name</label><input id="name" name="name" required minlength="2" maxlength="60" autocomplete="name" placeholder="e.g. Aditi Sharma"></div>':''}<div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" required autocomplete="email" placeholder="you@example.com"></div><div class="field"><label for="password">Demo password</label><input id="password" name="password" type="password" required minlength="8" maxlength="100" autocomplete="${authMode==='login'?'current-password':'new-password'}" placeholder="At least 8 characters"></div>${error?`<div class="error" role="alert">${esc(error)}</div>`:''}<button class="btn full" ${busy?'disabled':''}>${busy?'Please wait…':authMode==='login'?'Sign in':'Create demo account'} ${icon('arrow')}</button></form><div class="divider"></div><button class="btn secondary full" data-action="demo" ${busy?'disabled':''}>Explore with a demo account ${icon('arrow')}</button><div class="notice">Simulated authentication · ${backendEnabled()?'Accounts and bookings are saved on the shared demo server. Use fictional details.':'Accounts and journeys are saved in this browser only.'} Use a made-up email and a password you don’t use elsewhere.</div><div class="auth-small">No real payments. No live train data. Just the joy of planning.</div></div></section></div>`;}
function heading(title,sub){return`<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div><span class="date-label">${icon('calendar')}${new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',weekday:'short',day:'numeric',month:'short',year:'numeric'}).format(new Date())}</span></div>`;}
function dashboard(){const terminalNotice=('LKO'===searched.from||'LJN'===searched.from||'LKO'===searched.to||'LJN'===searched.to)?'<div class="notice terminal-note">Showing trains from and to both Lucknow terminals (LKO and LJN). Confirm the exact station listed on each train before booking.</div>':'';return`${heading('Where will you go next?',`Good to see you, ${esc(user.name.split(' ')[0])}. Let’s find your next journey.`)}<section class="hero"><div class="hero-copy"><div class="eyebrow">INDIA, ONE JOURNEY AT A TIME</div><h2>A window seat.<br>A world of possibilities.</h2><p>Find your route. Make a memory. Enjoy the ride.</p></div>${art}</section><div class="dashboard"><div class="stack"><section class="card search-card"><div class="card-title">${icon('ticket')}<h2>Book your journey</h2></div><form id="search-form"><div class="station-fields"><div class="field"><label for="from">FROM STATION</label><select id="from" name="from">${stations(query.from)}</select></div><button type="button" class="swap" data-action="swap" aria-label="Swap stations">${icon('swap')}</button><div class="field"><label for="to">TO STATION</label><select id="to" name="to">${stations(query.to)}</select></div></div><div class="form-grid"><div class="field"><label for="date">JOURNEY DATE</label><input id="date" name="date" type="date" min="${today()}" max="${addDays(today(),120)}" value="${query.date}" required></div><div class="field"><label for="quota">QUOTA</label><select id="quota" name="quota">${options({GENERAL:'General',TATKAL:'Tatkal (simulated)'},query.quota)}</select></div><div class="field"><label for="count">PASSENGERS</label><select id="count" name="count">${options(Object.fromEntries(Array.from({length:6},(_,i)=>[i+1,`${i+1} passenger${i?'s':''}`])),String(query.count))}</select></div></div>${error?`<div class="error" role="alert" style="margin-top:15px">${esc(error)}</div>`:''}<button class="btn full">${icon('search')}Search trains ${icon('arrow')}</button><p class="tiny muted" style="text-align:center;margin-top:13px">Reference train names · schedule snapshot · demo inventory</p></form></section><section><div class="section-head"><h3>More than a ticket</h3><span class="tiny muted">Passenger services</span></div><div class="quick-grid">${[['pnr','ticket','PNR status'],['track','pin','Train tracking'],['food','food','Order a meal']].map(([p,i,n])=>`<button class="quick" data-nav="${p}">${icon(i)}<span>${n}</span></button>`).join('')}</div></section><section class="card route-card"><div class="eyebrow muted" style="margin-bottom:10px">A COUNTRY OF POSSIBILITIES</div><h3>Different directions.<br>Beautiful destinations.</h3><p>Explore a sample route across India.</p>${[['NDLS','PNBE','Delhi → Patna'],['CSMT','PUNE','Mumbai → Pune'],['MAS','HWH','Chennai → Kolkata'],['NDLS','GHY','Delhi → Guwahati'],['TVC','MAQ','Kerala → Mangaluru'],['ADI','JP','Ahmedabad → Jaipur']].map(([a,b,n])=>`<button class="popular" data-route="${a},${b}">${n} ↗</button>`).join('')}</section></div><section><div class="section-head"><div><h2>Your train, your way</h2><p class="tiny muted" style="margin-top:5px">${esc(STATIONS[searched.from])} → ${esc(STATIONS[searched.to])} · ${esc(searched.date)}</p></div><span class="badge">${results().length} JOURNEY OPTIONS</span></div>${terminalNotice}<div class="results-toolbar"><label for="filter">Train type</label><select id="filter">${options({All:'All trains',Premium:'Premium',Vande_Bharat:'Vande Bharat',Vande_Bharat_Sleeper:'Vande Bharat Sleeper',Superfast:'Superfast',Express:'Express'},filter)}</select><label for="sort" style="margin-left:auto">Sort by</label><select id="sort">${options({departure:'Departure',duration:'Fastest first',price:'Lowest fare'},sort)}</select></div>${results().length?results().slice(0,visibleResultCount).map((item,index)=>journeyCard(item,index)).join(''):`<div class="card empty">${icon('search')}<h3>No sample journey found</h3><p>We couldn’t find a direct train or a timed one-change connection for this route and date. Try another date or a nearby station.</p></div>`}${results().length>visibleResultCount?`<button class="btn secondary full" data-more-results>Show ${Math.min(12,results().length-visibleResultCount)} more · ${results().length-visibleResultCount} remaining</button>`:''}<p class="result-caption">${icon('check')} Reference schedule routes · Simulated availability · Demo fares include taxes & fees</p></section></div>`;}
function results(){const key=JSON.stringify([searched.from,searched.to,searched.date,searched.cls,searched.count,searched.quota,filter,sort]);if(key===journeyResultsCacheKey)return journeyResultsCache;journeyResultsCacheKey=key;const direct=TRAINS.map(t=>({t,r:routeForSearch(t,searched.from,searched.to,searched.date)})).filter(x=>x.r&&(filter==='All'||x.t.type===filter.replaceAll('_',' ')));journeyResultsCache=direct.length?direct.sort((x,y)=>sort==='duration'?x.r.duration-y.r.duration:sort==='price'?fare(x.t,x.r,classForTrain(x.t),searched.count,searched.quota).total-fare(y.t,y.r,classForTrain(y.t),searched.count,searched.quota).total:((x.t.start+x.t.offsets[x.r.a])%1440)-((y.t.start+y.t.offsets[y.r.a])%1440)):findConnections(searched.from,searched.to,searched.date).filter(plan=>filter==='All'||plan.legs.every(leg=>leg.train.type===filter.replaceAll('_',' '))).map(plan=>({connection:true,plan})).sort((x,y)=>sort==='price'?connectionFare(x.plan)-connectionFare(y.plan):sort==='departure'?Date.parse(x.plan.legs[0].departure.iso)-Date.parse(y.plan.legs[0].departure.iso):x.plan.duration-y.plan.duration);return journeyResultsCache;}
function trainCard({t,r}){
  const cls=classForTrain(t),dep=journeyTime(t,r,r.a),arr=journeyTime(t,r,r.b,'arrival'),free=freeSeats(r,cls).length,q=queueCounts(r,cls),needsQueue=free<searched.count||q.racCount+q.waitlistCount>0,queue=queuePreview(r,cls,searched.count);
  const classes=classesFor(t).map(c=>`<button class="class-chip ${cls===c?'selected':''}" data-class="${c}" aria-pressed="${cls===c}" aria-label="Select ${CLASSES[c].name}, ${availabilityLabel(r,c,searched.count)}"><strong>${c} · ${money(fare(t,r,c,1,searched.quota).total)}</strong><span class="${availabilityTone(r,c,searched.count)}">${availabilityLabel(r,c,searched.count)}</span></button>`).join('');
  const stops=t.stops.map((s,i)=>`${esc(STATIONS[s])} (${s}) · ${journeyTime(t,r,i).time}${i===0?' (origin)':''}`).join('<br>');
  return`<article class="card train-card"><div class="train-top"><div><span class="train-number">${t.id} · REFERENCE · ${serviceDays(t)}</span><h3>${t.name}</h3><span class="tiny muted">Official listing: ${esc(t.officialName)}</span></div><button class="badge ${t.type==='Premium'||t.type.startsWith('Vande Bharat')?'amber':''}" data-detail="${t.id}" aria-label="View ${t.name} route">${t.type} ⓘ</button></div><div class="timing"><div><div class="time">${dep.time}</div><div class="station-name">${esc(STATIONS[r.from])} (${r.from})</div></div><div class="rail-line">${duration(r.duration)}<div class="track"></div>${r.b-r.a-1} intermediate stops</div><div class="arrival"><div class="time">${arr.time}</div><div class="station-name">${esc(STATIONS[r.to])} (${r.to})</div>${arr.date!==dep.date?`<div class="tiny muted">${arr.date}</div>`:''}</div></div><div class="class-grid">${classes}</div>${detailTrain===t.id?`<div class="train-detail"><strong>Reference route · all times IST</strong><br>Official enquiry listing: ${esc(t.officialName)}<br>${stops}<br>Each class uses an illustrative 24-seat inventory. Starting availability varies by train, class, travel date and route; your bookings and holds also reduce it. Berths are allotted automatically, then RAC up to three passenger positions, followed by a waitlist.</div>`:''}<div class="train-bottom"><div class="price">${money(fare(t,r,cls,searched.count,searched.quota).total)} <small>/ ${searched.count} traveller${searched.count>1?'s':''}</small></div><button class="btn ${needsQueue?'amber':''}" ${needsQueue?`data-book-queue="${t.id}" data-class-choice="${cls}"`:`data-book="${t.id}" data-class-choice="${cls}"`}>${needsQueue?`Request ${queue.label}`:'Book now'} ${icon('arrow')}</button></div></article>`;
}
function journeyCard(item,index){return item.connection?connectionCard(item.plan,index):trainCard(item);}
function connectionFare(plan){return plan.legs.reduce((sum,leg)=>sum+fare(leg.train,leg.route,classForTrain(leg.train),searched.count,searched.quota).total,0);}
function connectionCard(plan,index){const total=connectionFare(plan);return`<article class="card train-card connection-card"><div class="train-top"><div><span class="train-number">TWO-TRAIN CONNECTION · DEMO TIMETABLE</span><h3>${esc(STATIONS[searched.from])} to ${esc(STATIONS[searched.to])}</h3></div><span class="badge amber">CHANGE AT ${esc(STATIONS[plan.hub])}</span></div><div class="connection-legs">${plan.legs.map((leg,i)=>`<div class="connection-leg"><span class="train-number">LEG ${i+1} · ${leg.train.id}</span><strong>${esc(leg.train.name)}</strong><span>${esc(STATIONS[leg.route.from])} ${leg.departure.time} → ${esc(STATIONS[leg.route.to])} ${leg.arrival.time}</span><small>${leg.departure.date} · ${leg.route.duration<60?leg.route.duration+' min':duration(leg.route.duration)}</small></div>${i===0?`<div class="connection-wait">${duration(plan.transferMinutes)} transfer at ${esc(STATIONS[plan.hub])}</div>`:''}`).join('')}</div><div class="connection-summary"><span>2 separate demo tickets · about ${duration(plan.duration)} total</span><strong>${money(total)} / ${searched.count} traveller${searched.count===1?'':'s'}</strong></div><div class="notice">Availability is checked for each leg as you book. Each train gets its own payment simulation and PNR; book the second leg after the first ticket is issued.</div><div class="train-bottom"><div class="price">${money(total)} <small>combined sample fare</small></div><button class="btn" data-connection="${index}">Book this connection ${icon('arrow')}</button></div></article>`;}
function fareCard(b){return`<section class="card"><span class="eyebrow muted">YOUR JOURNEY</span><h3 style="margin:12px 0">${esc(b.trainName)} <span class="tiny muted">${b.trainId}</span></h3><p class="tiny muted">${esc(STATIONS[b.from])} → ${esc(STATIONS[b.to])}</p><div class="divider"></div><div class="fare-row"><span>Departure</span><strong>${b.departure.date} · ${b.departure.time}</strong></div><div class="fare-row"><span>Class / quota</span><strong>${b.cls} / ${b.quota}</strong></div><div class="fare-row"><span>Travellers</span><strong>${b.passengers.length}</strong></div><div class="divider"></div><h3>Fare summary</h3>${fareRows(b.fare)}<div class="notice">Demo amounts only. No money will be charged. ${b.queueRequested?'Your simulated RAC/WL place is assigned after payment.':'Seats are reserved atomically when you complete simulated payment.'}</div></section>`;}
function fareRows(f){return[['Base fare',f.base],['Reservation charge',f.reservation],['Tatkal charge',f.quotaCharge],['GST (simulated)',f.tax],['Demo service fee',f.service],['Total',f.total]].map(([l,n])=>`<div class="fare-row ${l==='Total'?'total':''}"><span>${l}</span><strong>${money(n)}</strong></div>`).join('');}
function checkout(){
  if(!draft){page='book';return dashboard();}
  const free=freeSeats(draft,draft.cls),queue=queuePreview(draft,draft.cls,draft.passengers.length),counts=queueCounts(draft,draft.cls);
  const queueActive=counts.racCount+counts.waitlistCount>0;
  const seatStatus=free.length>0&&!queueActive?`AVL ${free.length}`:queue.label;
  const seatStatusTone=seatStatus.startsWith('AVL')?'':'amber';
  return`${heading('Your journey is coming together.','A few details, and you’re on your way — in demo mode.')}<div class="stepper">${['Passengers','Simulated payment','Your ticket'].map((n,i)=>`<span class="${step===i+1?'current':''}"><b>${i+1}</b>${n}</span>`).join('')}</div><div class="checkout"><section class="card">${step===1?`<form id="passenger-form"><div class="row between"><h2>${draft.queueRequested?'Choose your queue':'Passenger details'}</h2><span class="badge ${draft.queueRequested?'amber':seatStatusTone}">${draft.queueRequested?queue.label:`${draft.cls} · ${CLASSES[draft.cls].coach} · ${seatStatus}`}</span></div>${draft.queueRequested?`<div class="notice queue-notice"><strong>${queue.label}</strong> · If seats become free before payment completes, the booking may be confirmed instead. This is a simulated queue, not a live railway status.</div>`:free.length<draft.passengers.length||queueActive?`<div style="margin-top:16px"><button type="button" class="btn amber" data-action="queue-mode">Request ${queue.label} instead</button></div>`:''}<div class="divider"></div><h3>Who’s travelling?</h3><p class="tiny muted" style="margin:9px 0 20px">Use fictional passenger details for this demo.</p>${draft.passengers.map((p,i)=>`<div class="passenger"><div class="row between"><strong class="tiny">PASSENGER ${i+1}</strong><span class="tiny muted">${draft.queueRequested?`${queue.status==='RAC'?'RAC':'WL'} ${queue.position+i}`:''}</span></div><div class="passenger-fields"><div class="field"><label for="pname-${i}">Full name</label><input id="pname-${i}" name="pname-${i}" required minlength="2" maxlength="60" value="${esc(p.name)}" placeholder="Passenger name"></div><div class="field"><label for="age-${i}">Age</label><input id="age-${i}" name="age-${i}" required type="number" min="1" max="120" value="${esc(p.age)}"></div><div class="field"><label for="gender-${i}">Gender</label><select id="gender-${i}" name="gender-${i}">${options({Female:'Female',Male:'Male',Other:'Other'},p.gender)}</select></div></div></div>`).join('')}<div class="field" style="margin-top:18px"><label for="boarding">Boarding point</label><select id="boarding" name="boarding">${TRAINS.find(t=>t.id===draft.trainId).stops.slice(draft.a,draft.b).map(s=>`<option value="${s}" ${draft.boarding===s?'selected':''}>${esc(STATIONS[s])} (${s})</option>`).join('')}</select><p class="tiny muted">Your simulated request covers the full booked route, including when you board later.</p></div>${error?`<div class="error" role="alert" style="margin-top:18px">${esc(error)}</div>`:''}<div class="row between" style="margin-top:23px"><button type="button" class="btn secondary" data-nav="book">Back to trains</button><button class="btn">Continue ${icon('arrow')}</button></div></form>`:`<form id="payment-form"><div class="badge amber">SIMULATED PAYMENT</div><h2 style="margin-top:16px">The last stop before your ticket.</h2><p class="support-copy" style="margin-top:10px">No card details, UPI credentials or bank information are collected. This step records only a simulated payment; no real money moves. ${draft.queueRequested?'No seat is held for a queue request; its status is assigned after payment.':backendEnabled()?'Your reservation is held for five minutes.':'Availability is checked again before your booking is confirmed.'}</p><div class="payment-box"><strong>Choose a simulation</strong><label><input type="radio" name="outcome" value="success" checked> Successful demo payment</label><label><input type="radio" name="outcome" value="failure"> Failed payment — test error handling</label></div><div class="support-copy">${draft.passengers.map((p,i)=>`${esc(p.name)} · ${p.age} · ${esc(p.gender)}${draft.queueRequested?` · ${queue.status==='RAC'?'RAC':'WL'} ${queue.position+i}`:''}`).join('<br>')}</div><label class="checkbox-line"><input type="checkbox" name="consent" required> I understand this is a simulated booking and this ticket is not valid for travel.</label>${error?`<div class="error" role="alert">${esc(error)}</div>`:''}<div class="row between" style="margin-top:23px"><button type="button" class="btn secondary" data-action="back-seats" ${busy?'disabled':''}>Back</button><button class="btn amber" ${busy?'disabled':''}>${busy?'Reserving…':'Simulate payment · '+money(draft.fare.total)}</button></div></form>`}</section>${fareCard(draft)}</div>`;
}
function ticketPage(){
  const b=viewTicket;
  if(!b)return`<div class="card empty">No ticket selected.</div>`;
  const cancelled=b.status==='CANCELLED',queued=b.status==='RAC'||b.status==='WAITLISTED';
  const headline=b.status==='CONFIRMED'?'You’re all set for your demo journey.':b.status==='RAC'?'Your demo journey is in RAC.':b.status==='WAITLISTED'?'Your demo journey is waitlisted.':'This demo ticket has been cancelled.';
  const message=b.status==='CONFIRMED'?'Your simulated payment and reservation are complete.':queued?`Your simulated payment is recorded. Current position: ${bookingStatusLabel(b)}. Queue positions can change after cancellations.`:'Seats or queue position released. Full simulated refund recorded.';
  return`<div class="success-heading"><div class="check">${cancelled?'×':'✓'}</div><h1>${headline}</h1><p>${message} No real payment occurred.</p></div><section class="ticket card" id="ers-ticket"><header class="ticket-header">${brand}<div style="text-align:right"><div class="eyebrow">ELECTRONIC RESERVATION SLIP</div><span class="tiny" style="color:#c7d9c7">DEMO · NOT VALID FOR TRAVEL</span></div></header><div class="ticket-body"><div class="row between"><div><span class="tiny muted">PNR NUMBER</span><h2 class="mono" style="margin-top:5px">${b.pnr}</h2></div><span class="badge ${cancelled?'red':queued?'amber':''}">${bookingStatusLabel(b)} · DEMO</span></div><div class="ticket-meta"><div><small>TRAIN NAME / NUMBER</small><strong>${esc(b.trainName)} (${b.trainId})</strong></div><div><small>CLASS / QUOTA</small><strong>${CLASSES[b.cls].name} (${b.cls}) / ${b.quota}</strong></div><div><small>BOOKED ON (IST)</small><strong>${new Date(b.bookedAt).toLocaleDateString('en-IN',{timeZone:'Asia/Kolkata'})}</strong></div><div><small>FROM</small><strong>${esc(STATIONS[b.from])} (${b.from})</strong></div><div><small>TO</small><strong>${esc(STATIONS[b.to])} (${b.to})</strong></div><div><small>BOARDING POINT</small><strong>${esc(STATIONS[b.boarding])} (${b.boarding})</strong></div><div><small>DEPARTURE (IST)</small><strong>${b.departure.date} · ${b.departure.time}</strong></div><div><small>ARRIVAL (IST)</small><strong>${b.arrival.date} · ${b.arrival.time}</strong></div><div><small>BOARDING TIME (IST)</small><strong>${b.boardingTime.date} · ${b.boardingTime.time}</strong></div></div><table><thead><tr><th>PASSENGER</th><th>AGE / GENDER</th><th>COACH / SEAT / QUEUE</th><th>STATUS</th></tr></thead><tbody>${b.passengers.map((p,i)=>`<tr><td>${i+1}. ${esc(p.name)}</td><td>${p.age} / ${esc(p.gender)}</td><td>${b.status==='CONFIRMED'?`${CLASSES[b.cls].coach} / ${b.seats[i]} (${berth(b.seats[i],b.cls)})`:cancelled?'—':`${b.status==='RAC'?'RAC':'WL'} ${(b.queuePosition??1)+i}`}</td><td>${passengerStatusLabel(b,i)}</td></tr>`).join('')}</tbody></table><div class="form-grid" style="margin-top:15px"><div>${fareRows(b.fare)}${b.refund?`<div class="notice">Simulated refund: ${money(b.refund)}</div>`:''}</div><div class="notice" style="align-self:start;margin:15px 0 0 15px"><strong>Please remember</strong><br>This is a sample ERS generated by RailYatra. All schedules, fares, seat assignments, payment and booking statuses are simulated. It is not an official railway ticket.</div></div><div class="ticket-footer"><div><strong class="tiny">A journey worth taking.</strong><p class="tiny muted" style="margin-top:6px">Demo transaction: ${esc(b.paymentId.slice(0,18))}<br>No live railway / IRCTC API. Not valid for travel.<br>QR contains a demo PNR only; it cannot verify a railway booking.</p></div><img id="ticket-qr" class="qr" alt="Demo QR code containing demo PNR ${b.pnr}"></div></div></section>${connectionFlow&&connectionLegIndex<connectionFlow.length-1&&!cancelled?`<section class="card connection-next"><h3>Next: change trains at ${esc(STATIONS[connectionFlow[connectionLegIndex].route.to])}</h3><p>Leg ${connectionLegIndex+1} is booked. The next train is ${esc(connectionFlow[connectionLegIndex+1].train.name)} (${connectionFlow[connectionLegIndex+1].train.id}), departing ${esc(STATIONS[connectionFlow[connectionLegIndex+1].route.from])} at ${connectionFlow[connectionLegIndex+1].departure.time}. It will have its own simulated payment and PNR.</p><button class="btn" data-connection-next>Book next leg ${icon('arrow')}</button></section>`:''}<div class="download-row"><button class="btn" data-download="pdf">${icon('download')}Download PDF</button><button class="btn secondary" data-download="png">${icon('download')}Download PNG</button></div><div style="text-align:center"><button class="text-btn" data-nav="journeys">View my journeys →</button><button class="text-btn" data-nav="book">Book another journey →</button></div>`;
}
function servicePage(){
  if(page==='pnr')return pnrPage();
  if(page==='track')return trackingPage();
  if(page==='food')return foodPage();
  if(page==='journeys')return journeysPage();
  if(page==='transactions')return transactionsPage();
  const shared=backendEnabled();
  return `${heading('A demo with a sense of direction.','How RailYatra works, and where the simulation stops.')}<div class="card support-copy"><h2>Independent. Simulated. ${shared?'Shared demo backend.':'Browser-local.'}</h2><h3>Sample schedules & fares</h3><p>Explore ${Object.keys(STATIONS).length} sample stations and ${TRAINS.length} directional train services. Train numbers are cross-checked against the official Indian Railways enquiry list; official listing labels appear on each service. Route stops, running days and times come from a public timetable snapshot. Search direct trains or a timed one-change connection at a shared station. Lucknow searches include both Lucknow Charbagh (LKO) and Lucknow Junction (LJN); each train shows its actual terminal. Connected journeys use two separate reservations, payments and PNRs; the next-leg booking is offered after the first ticket. This curated sample does not include every Indian Railways service, and the route/timing snapshot can be out of date. Verify train schedules with official railway sources before travel.</p><h3>Seats that understand the journey</h3><p>Each class uses an illustrative 24-seat inventory. A deterministic sample-demand model starts trains with different availability by service type, class, route span, travel date and how close departure is; the same search stays stable on refresh. Confirmed demo bookings and temporary holds reduce availability, while cancellations and expired or failed payments release seats. If a requested party cannot be confirmed or an earlier queue exists, passengers can join RAC (up to three passenger positions) and then a numbered waitlist; cancellations can promote queued bookings. A reservation occupies half-open route segments [origin, destination). Delhi → Kanpur and Kanpur → Patna can reuse a seat; Delhi → Prayagraj and Kanpur → Patna cannot. The key includes train, class and the train’s origin departure date, including journeys that board after midnight. Generated demand is illustrative, not railway inventory.</p><h3>${shared?'Atomic reservation, shared inventory':'Atomic reservation, browser-local inventory'}</h3><p>${shared?'The API checks availability again inside a PostgreSQL transaction, locks the class inventory briefly, automatically allots available seats and creates short-lived holds. Competing users cannot reserve the same seat on overlapping segments.':'IndexedDB serializes read/write transactions across tabs in the same browser origin. Availability is checked again and the whole booking is inserted atomically after successful simulated payment.'} Failed simulations reserve nothing. Cancelling releases confirmed seats or queue positions and may promote the next eligible queued booking; linked food orders are cancelled atomically. Route and timetable records are reference data; availability, tracking and payments remain simulated. There is no live railway connection.</p><h3>Demo accounts & privacy</h3><p>${shared?'Passwords are hashed on the server with scrypt; short-lived API sessions are stored in this browser. The shared demo sign-in is public, so use fictional passenger data.':'Accounts use a salted SHA-256 password digest in IndexedDB. Session details are stored in localStorage. Use fictional data. Logging out preserves journeys; clearing browser site data erases demo records.'} This is a learning demo, not production authentication.</p><h3>Tracking, food & cancellations</h3><p>Tracking is an interactive sample timeline, not GPS or railway data. ${shared?'Meal orders are stored in the shared demo database but are not paid or delivered.':'Meal orders are stored in this browser but are not paid or delivered.'} Upcoming tickets receive a full simulated refund when cancelled. PNR enquiry is scoped to the signed-in demo account. PDF and PNG downloads are generated in your browser and include a demo QR.</p></div>`;
}
function journeysPage(){let list=mine().filter(b=>historyTab==='upcoming'?['CONFIRMED','RAC','WAITLISTED'].includes(b.status)&&Date.parse(b.departure.iso)>=Date.now():historyTab==='past'?['CONFIRMED','RAC','WAITLISTED'].includes(b.status)&&Date.parse(b.departure.iso)<Date.now():b.status==='CANCELLED').sort((a,b)=>b.departure.iso.localeCompare(a.departure.iso));return`${heading('Your journeys, in one place.','The ones ahead. The memories behind. All simulated.')}<div class="service-tabs">${['upcoming','past','cancelled'].map(t=>`<button class="${historyTab===t?'active':''}" data-history="${t}">${t[0].toUpperCase()+t.slice(1)} journeys</button>`).join('')}</div>${list.length?list.map(b=>`<article class="card journey"><div><div class="row"><span class="badge ${b.status==='CANCELLED'?'red':b.status==='RAC'||b.status==='WAITLISTED'?'amber':''}">${bookingStatusLabel(b)}</span><span class="tiny muted">PNR ${b.pnr}${b.sample?' · SAMPLE HISTORY':''}</span></div><h3 style="margin-top:13px">${esc(STATIONS[b.from])} → ${esc(STATIONS[b.to])}</h3><p>${esc(b.trainName)} (${b.trainId}) · ${b.departure.date} · ${b.departure.time} IST</p><p>${b.cls} · ${b.passengers.length} passenger(s) · ${money(b.fare.total)}</p></div><div class="journey-actions"><button class="btn secondary" data-ticket="${b.pnr}">${icon('ticket')}View ticket</button>${historyTab==='upcoming'?`${b.status==='CONFIRMED'?`<button class="btn secondary" data-food="${b.pnr}">${icon('food')}Food</button>`:''}<button class="btn danger" data-cancel="${b.pnr}">Cancel</button>`:''}</div></article>`).join(''):`<div class="card empty">${icon('calendar')}<h3>No ${historyTab} journeys yet</h3><p>${historyTab==='upcoming'?'Your next adventure starts with a search.':historyTab==='past'?'Completed journeys appear here after their scheduled departure.':'Cancelled demo tickets will appear here.'}</p><button class="btn" data-nav="book" style="margin-top:20px">Find a journey ${icon('arrow')}</button></div>`}`;}
function pnrPage(){return`${heading('A little peace of mind.','Look up a 10-digit PNR from your demo bookings.')}<div class="service-layout stack"><section class="card"><h2>PNR enquiry</h2><form id="pnr-form" class="row" style="margin-top:22px"><div class="field" style="flex:1"><label for="pnr">DEMO PNR NUMBER</label><input id="pnr" name="pnr" required inputmode="numeric" pattern="[0-9]{10}" maxlength="10" placeholder="10-digit PNR" value="${esc(pnrResult?.pnr??'')}"></div><button class="btn" style="align-self:end">Check status</button></form>${error?`<div class="error" role="alert" style="margin-top:18px">${esc(error)}</div>`:''}<p class="tiny muted" style="margin-top:15px">Only PNRs from this signed-in demo account can be looked up.</p></section>${pnrResult?`<section class="card"><div class="row between"><h3>${esc(pnrResult.trainName)}</h3><span class="badge ${pnrResult.status==='CANCELLED'?'red':pnrResult.status==='RAC'||pnrResult.status==='WAITLISTED'?'amber':''}">${bookingStatusLabel(pnrResult)}</span></div><p class="muted" style="margin-top:15px">${esc(STATIONS[pnrResult.from])} → ${esc(STATIONS[pnrResult.to])}</p><p class="tiny muted" style="margin-top:9px">${pnrResult.departure.date} · ${pnrResult.departure.time} IST · ${pnrResult.cls} · ${pnrResult.passengers.length} passengers</p><div class="divider"></div>${pnrResult.passengers.map((p,i)=>`<div class="fare-row"><span>${esc(p.name)}</span><strong>${pnrResult.status==='CONFIRMED'?`${CLASSES[pnrResult.cls].coach} / ${pnrResult.seats[i]} · CNF`:pnrResult.status==='CANCELLED'?'Cancelled':passengerStatusLabel(pnrResult,i)}</strong></div>`).join('')}<button class="btn secondary" data-ticket="${pnrResult.pnr}">View demo ticket ${icon('arrow')}</button></section>`:''}</div>`;}
function trackingPage(){const t=TRAINS.find(t=>t.id===tracking?.id);const pos=tracking?.pos??0;return`${heading('Follow the journey.','Simulated station progress — no live GPS or railway feed.')}<div class="service-layout stack"><section class="card"><h2>Track a sample train</h2><form id="track-form" class="form-grid" style="margin-top:22px"><div class="field"><label for="track-train">TRAIN</label><select id="track-train" name="train">${options(Object.fromEntries(TRAINS.map(t=>[t.id,`${t.id} · ${t.name}`])),tracking?.id??TRAINS[0].id)}</select></div><div class="field"><label for="track-date">ORIGIN DEPARTURE DATE</label><input id="track-date" name="date" type="date" value="${tracking?.date??today()}" required></div><button class="btn span2">Show simulated progress</button></form></section>${t?`<section class="card"><div class="row between"><h2>${esc(t.name)}</h2><span class="badge amber">SIMULATED</span></div><div class="notice" style="margin:18px 0">Demo train ${pos===t.stops.length-1?'has reached its destination':'is at '+esc(STATIONS[t.stops[pos]])}. Advance the timeline to explore the route. This is not a live train position.</div><div style="margin:28px 0 0">${t.stops.map((s,i)=>`<div class="tracker-stop ${i<=pos?'passed':''} ${i===pos?'current':''}"><div class="row between"><strong>${esc(STATIONS[s])} (${s})</strong><span class="tiny muted">${journeyTime(t,{originDate:tracking.date},i).time} IST</span></div><p>${journeyTime(t,{originDate:tracking.date},i).date} · ${i<pos?'Passed (demo)':i===pos?'Current station (demo)':'Upcoming (demo)'}</p></div>`).join('')}</div><div class="row"><button class="btn secondary" data-action="track-reset">Reset simulation</button><button class="btn" data-action="track-next" ${pos===t.stops.length-1?'disabled':''}>Next station ${icon('arrow')}</button></div></section>`:''}</div>`;}
const menu=[{id:'thali',name:'Homestyle veg thali',desc:'Dal, seasonal sabzi, rice & rotis',price:180,emoji:'🍱'},{id:'biryani',name:'Vegetable biryani',desc:'Fragrant rice, vegetables & raita',price:150,emoji:'🍚'},{id:'snack',name:'Chai & snack combo',desc:'Masala chai, samosas & a little joy',price:80,emoji:'☕'}];
function foodPage(){const trips=upcoming().filter(b=>b.status==='CONFIRMED');if(!trips.some(b=>b.pnr===foodJourney))foodJourney=trips[0]?.pnr??'';const b=trips.find(b=>b.pnr===foodJourney);const ownOrders=orders.filter(o=>o.email===user.email);return`${heading('Good food. Great journeys.','A little comfort, delivered to your demo seat.')}<div class="service-layout stack"><section class="card"><div class="row between"><h2>Food on board</h2><span class="badge amber">SIMULATED ORDERS</span></div>${b?`<div class="form-grid" style="margin-top:20px"><div class="field"><label for="food-journey">YOUR UPCOMING JOURNEY</label><select id="food-journey">${options(Object.fromEntries(trips.map(b=>[b.pnr,`${b.pnr} · ${STATIONS[b.from]} → ${STATIONS[b.to]}`])),foodJourney)}</select></div><div class="field"><label for="food-station">DELIVERY STATION</label><select id="food-station">${TRAINS.find(t=>t.id===b.trainId).stops.slice(TRAINS.find(t=>t.id===b.trainId).stops.indexOf(b.boarding),b.b).map(s=>`<option value="${s}">${esc(STATIONS[s])} (${s})</option>`).join('')}</select></div></div><p class="tiny muted" style="margin-top:14px">One meal per click for the first passenger. No payment or real delivery. Repeated clicks place additional meals.</p>`:`<div class="empty">${icon('food')}<h3>A ticket first, a treat next.</h3><p>Book an upcoming demo journey to order food.</p><button class="btn" data-nav="book" style="margin-top:18px">Book a journey</button></div>`}</section><div class="food-grid">${menu.map(m=>`<article class="card food-card"><div class="food-emoji" aria-hidden="true">${m.emoji}</div><div><h3>${m.name}</h3><p class="tiny muted">${m.desc}</p><button class="btn secondary full" data-meal="${m.id}" ${b?'':'disabled'}>Order demo meal · ${money(m.price)}</button></div></article>`).join('')}</div>${ownOrders.length?`<section class="card"><h3>Your demo meal orders</h3>${ownOrders.slice().reverse().map(o=>`<div class="transaction"><div><h3>${esc(o.name)}</h3><p>PNR ${o.pnr} · ${esc(STATIONS[o.station])} · ${o.id.slice(0,8)}</p></div><div style="text-align:right"><span class="badge ${o.status==='CANCELLED'?'red':''}">${o.status}</span><p>${money(o.price)} · simulated</p></div></div>`).join('')}</section>`:''}</div>`;}
function transactionsPage(){
  const paymentItems=backendEnabled()
    ? transactions.map(tx=>({kind:(tx.kind==='PAYMENT'?'Payment':'Refund')+' · '+tx.status,at:tx.createdAt,amount:tx.amount,pnr:tx.pnr||('Checkout '+String(tx.checkoutId||'').slice(0,8)),type:'DEMO '+tx.status}))
    : mine().flatMap(b=>[{kind:'Booking · '+b.trainName,at:b.bookedAt,amount:b.fare.total,pnr:b.pnr,type:'DEMO PAYMENT',sample:b.sample},...(b.cancelledAt?[{kind:'Full simulated refund',at:b.cancelledAt,amount:b.refund,pnr:b.pnr,type:'DEMO REFUND'}]:[])]);
  const foodItems=orders.filter(o=>o.email===user.email).map(o=>({kind:'Meal · '+o.name,at:o.createdAt,amount:o.price,pnr:o.pnr,type:o.status==='CANCELLED'?'MEAL CANCELLED':'DEMO FOOD ORDER'}));
  const items=paymentItems.concat(foodItems).sort((a,b)=>b.at.localeCompare(a.at));
  const rows=items.length?items.map(x=>'<div class="transaction"><div><h3>'+esc(x.kind)+'</h3><p>PNR '+esc(x.pnr)+' · '+new Date(x.at).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})+' IST'+(x.sample?' · seeded sample history':'')+'</p></div><div style="text-align:right"><strong>'+money(x.amount)+'</strong><p><span class="badge '+(x.type.includes('REFUND')?'amber':'')+'">'+esc(x.type)+'</span></p></div></div>').join(''):'<div class="empty">'+icon('wallet')+'<h3>A fresh start</h3><p>Your demo transactions will appear after a booking.</p></div>';
  return heading('Every little detail.','Your latest demo bookings, refunds and meal orders.')+'<div class="service-layout card"><h2>Latest transactions</h2>'+rows+'</div>';
}
function modalHtml(){if(!modal)return'';return`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><h2 id="modal-title">Cancel this demo journey?</h2><p>PNR ${modal.pnr}. Any passenger seats or queue positions will be released and linked demo meal orders will be cancelled. A full simulated refund of ${money(modal.fare.total)} will appear in transactions. No real money moves.</p><div class="row"><button class="btn secondary" data-action="close-modal">Keep journey</button><button class="btn danger" data-action="confirm-cancel">Cancel ticket</button></div></section></div>`;}
function capturePassengers(){if(!draft||!$('#passenger-form'))return;draft.passengers=draft.passengers.map((p,i)=>({name:$(`#pname-${i}`).value,age:$(`#age-${i}`).value,gender:$(`#gender-${i}`).value}));draft.boarding=$('#boarding').value;}
function captureQuery(){if(!$('#search-form'))return;const f=new FormData($('#search-form'));query={from:f.get('from'),to:f.get('to'),date:f.get('date'),cls:query.cls,quota:f.get('quota'),count:+f.get('count')};}
async function startConnectionLeg(){const leg=connectionFlow?.[connectionLegIndex];if(!leg)return;searched={...searched,from:leg.route.from,to:leg.route.to,date:leg.route.date};await refresh();startBooking(leg.train.id,false,leg,connectionPassengers);}
function startBooking(id,queueRequested=false,leg=null,passengers=null){const t=leg?.train??TRAINS.find(t=>t.id===id),r=leg?.route??routeForSearch(t,searched.from,searched.to,searched.date);if(!t||!r)throw Error('This sample train no longer matches the selected route. Search again.');if(Date.parse(journeyTime(t,r,r.a).iso)<=Date.now())throw Error('This sample train has already departed. Choose a later date.');const cls=classForTrain(t);draft={...r,email:user.email,trainName:t.name,cls,quota:searched.quota,queueRequested,passengers:passengers?.length?passengers.map(p=>({...p})):Array.from({length:searched.count},()=>({name:'',age:'',gender:'Female'})),seats:[],boarding:r.from,departure:journeyTime(t,r,r.a),arrival:journeyTime(t,r,r.b,'arrival'),fare:fare(t,r,cls,searched.count,searched.quota),paymentId:crypto.randomUUID(),checkoutKey:crypto.randomUUID()};page='checkout';step=1;error='';render();window.scrollTo(0,0);}
document.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el||el.disabled)return;try{if(el.dataset.moreResults){visibleResultCount+=12;render();}else if(el.dataset.nav){if(draft?.checkoutId){await releaseCheckout(draft.checkoutId);draft=null;}captureQuery();if(el.dataset.nav!=='ticket'){connectionFlow=null;connectionPassengers=[];if(connectionSearch){searched=connectionSearch;connectionSearch=null;}}page=el.dataset.nav;error='';render();window.scrollTo(0,0);}else if(el.dataset.auth){authMode=el.dataset.auth;error='';render();}else if(el.dataset.route){query={...query,from:el.dataset.route.split(',')[0],to:el.dataset.route.split(',')[1]};searched={...query};filter='All';visibleResultCount=12;error='';await refresh();render();}else if(el.dataset.class){captureQuery();query.cls=searched.cls=el.dataset.class;render();}else if(el.dataset.book||el.dataset.bookQueue){connectionFlow=null;connectionPassengers=[];query.cls=searched.cls=el.dataset.classChoice??searched.cls;await refresh();startBooking(el.dataset.book??el.dataset.bookQueue,Boolean(el.dataset.bookQueue));}else if(el.dataset.connection){const item=results()[Number(el.dataset.connection)];if(!item?.connection)throw Error('That connection is no longer available in the sample timetable.');connectionFlow=item.plan.legs;connectionLegIndex=0;connectionPassengers=[];connectionSearch={...searched};await startConnectionLeg();}else if(el.dataset.connectionNext){connectionLegIndex++;await startConnectionLeg();}else if(el.dataset.detail){captureQuery();detailTrain=detailTrain===el.dataset.detail?null:el.dataset.detail;render();}else if(el.dataset.ticket){connectionFlow=null;connectionPassengers=[];await refresh();viewTicket=mine().find(b=>b.pnr===el.dataset.ticket);page='ticket';render();window.scrollTo(0,0);}else if(el.dataset.history){historyTab=el.dataset.history;await refresh();render();}else if(el.dataset.cancel){modal=mine().find(b=>b.pnr===el.dataset.cancel);render();setTimeout(()=>$('[data-action="close-modal"]')?.focus(),0);}else if(el.dataset.food){foodJourney=el.dataset.food;page='food';render();}else if(el.dataset.meal){const m=menu.find(m=>m.id===el.dataset.meal);el.disabled=true;await orderFood({pnr:foodJourney,email:user.email,station:$('#food-station').value,name:m.name,price:m.price});await refresh();render();toast('Demo meal order placed. No payment or real delivery.');}else if(el.dataset.download){el.disabled=true;await downloadTicket(viewTicket,el.dataset.download);el.disabled=false;toast(`${el.dataset.download.toUpperCase()} ticket downloaded.`);}else if(el.dataset.action)await action(el.dataset.action);}catch(err){busy=false;error=err.message;toast(err.message);render();}});
async function action(a){if(a==='theme'){theme=theme==='dark'?'light':'dark';localStorage.setItem('ry-theme',theme);document.documentElement.dataset.theme=theme;const b=$('[data-action="theme"]');if(b)b.outerHTML=themeControl();return;}if(a==='logout'){await releaseCheckout(draft?.checkoutId);await logout();if(connectionSearch)searched=connectionSearch;user=null;localStorage.removeItem('ry-session');page='book';draft=null;viewTicket=null;pnrResult=null;foodJourney='';modal=null;error='';render();connectionFlow=null;connectionPassengers=[];connectionSearch=null;}if(a==='swap'){captureQuery();[query.from,query.to]=[query.to,query.from];render();}if(a==='demo'){busy=true;error='';render();const email='traveller@railyatra.demo';let u;if(backendEnabled()){const password='RailYatraDemo!2026';try{u=await authenticate(email,password);}catch(err){if(err.status!==401)throw err;try{u=await register('Aditi Sharma',email,password);}catch(createError){if(createError.status!==409)throw createError;u=await authenticate(email,password);}}}else{u=(await all('users')).find(account=>account.email===email);if(!u)u=await register('Aditi Sharma',email,crypto.randomUUID());}user=safeSession(u);localStorage.setItem('ry-session',JSON.stringify(user));await refresh();if(!backendEnabled()&&!mine().length){const t=TRAINS.find(t=>t.id==='12124'),r=routeFor(t,'PUNE','CSMT',addDays(today(),-7));await reserve({...r,email:user.email,trainName:t.name,cls:'3A',quota:'GENERAL',passengers:[{name:'Aditi Sharma',age:28,gender:'Female'}],seats:[],boarding:'PUNE',boardingTime:journeyTime(t,r,r.a),departure:journeyTime(t,r,r.a),arrival:journeyTime(t,r,r.b,'arrival'),fare:fare(t,r,'3A',1,'GENERAL'),paymentId:crypto.randomUUID(),sample:true});await refresh();}busy=false;render();}if(a==='queue-mode'){capturePassengers();draft.queueRequested=true;draft.seats=[];error='';render();}if(a==='back-seats'){await releaseCheckout(draft?.checkoutId);if(draft){draft.checkoutId=null;draft.checkoutExpiresAt=null;draft.checkoutKey=crypto.randomUUID();draft.seats=[];}step=1;error='';await refresh();render();}if(a==='close-modal'){modal=null;render();}if(a==='confirm-cancel'){const pnr=modal.pnr;await cancel(pnr,user.email);modal=null;await refresh();if(viewTicket?.pnr===pnr)viewTicket=mine().find(b=>b.pnr===pnr);if(pnrResult?.pnr===pnr)pnrResult=mine().find(b=>b.pnr===pnr);render();toast('Demo ticket cancelled. Seats released and simulated refund recorded.');}if(a==='track-next'){tracking.pos++;render();}if(a==='track-reset'){tracking.pos=0;render();}}
document.addEventListener('change',e=>{if(e.target.id==='filter'){captureQuery();filter=e.target.value;visibleResultCount=12;render();}if(e.target.id==='sort'){captureQuery();sort=e.target.value;visibleResultCount=12;render();}if(e.target.id==='food-journey'){foodJourney=e.target.value;render();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=null;render();}if(e.key==='Tab'&&modal){const buttons=[...document.querySelectorAll('.modal button')];if(e.shiftKey&&document.activeElement===buttons[0]){e.preventDefault();buttons.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===buttons.at(-1)){e.preventDefault();buttons[0].focus();}}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,f=new FormData(form);try{if(busy)return;error='';if(form.id==='auth-form'){busy=true;const mode=authMode;const email=f.get('email').trim().toLowerCase(),password=f.get('password');if(mode==='signup'&&f.get('name').trim().length<2)throw Error('Enter a name with at least two characters.');const u=mode==='signup'?await register(f.get('name').trim(),email,password):await authenticate(email,password);user=safeSession(u);localStorage.setItem('ry-session',JSON.stringify(user));busy=false;await refresh();render();}else if(form.id==='search-form'){captureQuery();if(query.from===query.to)throw Error('Choose two different stations.');if(query.date<today()||query.date>addDays(today(),120))throw Error('Choose a journey date within the next 120 days.');searched={...query};visibleResultCount=12;await refresh();render();}else if(form.id==='passenger-form'){capturePassengers();if(draft.passengers.some(p=>p.name.trim().length<2||!Number.isInteger(+p.age)||+p.age<1||+p.age>120))throw Error('Enter valid passenger names and whole-number ages between 1 and 120.');draft.passengers=draft.passengers.map(p=>({...p,name:p.name.trim(),age:+p.age}));const t=TRAINS.find(t=>t.id===draft.trainId);draft.boardingTime=journeyTime(t,draft,t.stops.indexOf(draft.boarding));if(backendEnabled()){busy=true;render();const held=await createCheckout(draft);draft.checkoutId=held.id;draft.checkoutExpiresAt=held.expiresAt;draft.seats=held.seats??[];busy=false;await refresh();}step=2;render();window.scrollTo(0,0);}else if(form.id==='payment-form'){if(busy)return;if(f.get('outcome')==='failure'){if(backendEnabled())await completeCheckout(draft.checkoutId,'FAILURE');else throw Error('Simulated payment failed. No seats were reserved and no money was charged. Try the successful simulation.');}busy=true;render();viewTicket=backendEnabled()?await completeCheckout(draft.checkoutId,'SUCCESS'):await reserve(draft);if(connectionFlow){connectionPassengers=viewTicket.passengers;if(connectionLegIndex>=connectionFlow.length-1)connectionFlow=null;}busy=false;await refresh();page='ticket';draft=null;render();window.scrollTo(0,0);}else if(form.id==='pnr-form'){await refresh();pnrResult=mine().find(b=>b.pnr===f.get('pnr').trim());if(!pnrResult)throw Error('PNR not found in this account. Use a demo PNR from My journeys.');render();}else if(form.id==='track-form'){tracking={id:f.get('train'),date:f.get('date'),pos:0};render();}}catch(err){busy=false;if(form.id==='payment-form'&&(err.status===402||err.status===409)){draft.checkoutId=null;draft.checkoutExpiresAt=null;draft.checkoutKey=crypto.randomUUID();draft.seats=[];step=1;await refresh();}else if(form.id==='passenger-form'&&err.status===409){await refresh();}error=err.message;render();}});
window.addEventListener('storage',e=>{if(e.key==='ry-session'){try{user=JSON.parse(e.newValue);}catch{user=null;}draft=null;page='book';pnrResult=null;viewTicket=null;refresh().then(render);}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&user){capturePassengers();captureQuery();}if(!document.hidden&&user)refresh().then(render).catch(e=>toast(e.message));});
try{if(user&&backendEnabled()&&!(await all('users')).some(u=>u.email===user.email)){user=null;localStorage.removeItem('ry-session');}await refresh();render();}catch(e){error=backendEnabled()?e.message:'Browser storage is unavailable. Enable site storage to use this demo.';user=null;localStorage.removeItem('ry-session');render();}
